(async()=>{'use strict';try{const state=await window.TestingAuth.requireAuth();if(!state)return;window.TestingShell.render(state);window.TestingSecurity.init();await window.TestingPages.init()}catch(e){console.error('[Testing Management]',e);document.body.innerHTML=`<main class="tm-page"><div class="tm-banner error"><strong>Unable to open Testing Management.</strong><div>${String(e?.message||e)}</div><div style="margin-top:12px"><a class="tm-btn primary" href="https://enterprise.screenings4u.com/portal-selector.html">Return to Enterprise</a></div></div></main>`}})();
